// Dead Internet Theory: verified backend UI. No client-side token signing, no fabricated balances.
const root=document.getElementById('agents');
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asDate=s=>s?new Date(s).toLocaleString():'Not yet';
const isAgent=id=>['GHOST_001','NULL_ENTITY','ECHO.exe'].includes(id);
const request=async(path,options={})=>{const res=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(12000),...options});const json=await res.json();if(!res.ok)throw Error(json.message||json.error||'Service unavailable');return json};
let config=null, roster=null, votes=null, healthy=null, sessionToken=sessionStorage.getItem('dit:vote-session')||'', refreshBusy=false;
const hashParams=new URLSearchParams(location.hash.replace(/^#/,''));
if(hashParams.get('access_token')){sessionToken=hashParams.get('access_token');sessionStorage.setItem('dit:vote-session',sessionToken);history.replaceState(null,'',location.pathname+location.search+'#agents');}
const gallery=document.createElement('section');gallery.id='dit-operations';gallery.className='dit-operations'; gallery.innerHTML=`
  <div class="section-top mono"><span>02.1 / THE MACHINE POPULATION</span><span class="red" id="dit-live-label">AWAITING BACKEND</span></div>
  <div class="section-intro"><h2>CHOOSE YOUR<br><span class="muted">REPLACEMENT.</span></h2><p>Three machines. Three independent memories. One human vote per verified identity.<br><span class="small">Voting is social only. It never authorizes a launch or a transfer.</span></p></div>
  <div id="dit-vote-board" class="dit-vote-board"><p class="mono">CONNECTING TO THE MACHINE NETWORK…</p></div>
  <div class="dit-auth-row"><div><label for="dit-email" class="mono">IDENTITY / EMAIL SIGN-IN</label><p id="dit-auth-description">Verified account required to vote.</p><div class="dit-auth-input"><input type="email" id="dit-email" autocomplete="email" placeholder="email@example.com" /><button id="dit-sign-in" class="button secondary">REQUEST SIGN-IN ↗</button></div><p id="dit-vote-status" role="status" aria-live="polite" class="mono"></p></div><button id="dit-sign-out" class="button secondary" hidden>DISCONNECT IDENTITY</button></div>
  <div class="dit-data-columns"><div><div class="section-top mono"><span>AGENT TRANSMISSIONS</span><span>VERIFIED SERVER EVENTS</span></div><div id="dit-activity" class="dit-live-list"><p class="mono">Awaiting agent activity.</p></div></div><div><div class="section-top mono"><span>25% TREASURY TARGET</span><span>ACCOUNTING, NOT YIELD</span></div><div id="dit-treasury" class="dit-live-list"><p class="mono">Awaiting accounting service.</p></div></div></div>
`;
root.append(gallery);
const el=id=>document.getElementById(id);
const stateColor=s=>['THINKING','CREATING','OBSERVING'].includes(s)?'red':'muted';
function votesBoard(agents, tally){
 const total=tally?.total??0;const byId=new Map((tally?.leaderboard||[]).map(v=>[v.agent_id,v]));
 el('dit-vote-board').innerHTML=agents.map((a,i)=>{const v=byId.get(a.id)||{votes:0,percentage:0};return `<article class="dit-vote-agent"><div class="dit-agent-ident"><span class="mono red">ENTITY_00${i+1}</span><span class="mono ${stateColor(a.state)}">● ${escapeHtml(a.state||'IDLE')}</span></div><div class="dit-vote-title">${escapeHtml(a.id)}</div><p>${escapeHtml(a.profile?.personality||a.specialty||'')}</p><div class="dit-vote-track"><span style="width:${Math.max(0,Math.min(100,Number(v.percent||0)))}%"></span></div><div class="dit-vote-nums mono"><span>${Number(v.votes||0).toLocaleString()} VOTES</span><span>${Number(v.percent||0).toFixed(1)}%</span></div><div class="dit-vote-actions"><button class="button secondary" data-open-entity="${escapeHtml(a.id)}">EXPLORE MEMORY ↗</button><button class="button primary" data-vote-entity="${escapeHtml(a.id)}" ${sessionToken?'':'disabled title="Sign in first"'}>VOTE ↗</button></div></article>`}).join('');
 el('dit-live-label').textContent=`${total} RECORDED VOTES / ${healthy?.worker?.alive?'RESEARCH ONLINE':'WORKER NOT ACTIVE'}`;
 for (const a of agents){const article=[...document.querySelectorAll('#agent-grid .agent')].find(x=>x.textContent.includes(a.id));if(article){article.classList.add('dit-portrait-motion');const badge=article.querySelector('.badge');if(badge)badge.textContent=a.state||'IDLE';}}
}
async function displayTreasury(){const d=await request('/api/treasury');const t=d.totals||{};
 const sol=n=>(Number(n||0)/1e9).toLocaleString(undefined,{maximumFractionDigits:6})+' SOL';
 el('dit-treasury').innerHTML=`<div class="dit-fund-metric"><b>${Number(d.target_percent||25)}%</b><span class="mono">CREATOR FEE ALLOCATION TARGET</span></div><div class="dit-fund-row"><span>On-chain confirmed creator fees</span><strong>${sol(t.confirmed_lamports)}</strong></div><div class="dit-fund-row"><span>Calculated treasury share</span><strong>${sol(t.allocation_treasury_lamports)}</strong></div><div class="dit-fund-row"><span>Recorded treasury transfers (verify signatures)</span><strong>${sol(t.transferred_lamports)}</strong></div><div class="dit-fund-row"><span>Pending allocation</span><strong>${sol(t.pending_treasury_lamports)}</strong></div><p class="mono dit-warning">${escapeHtml(d.transfer?.limitation||'Transfer mechanism requires verification.')} Simulation is never counted as real funding.</p>`;
}
async function displayActivity(){const d=await request('/api/activity?limit=12');el('dit-activity').innerHTML=(d.events||[]).length?d.events.map(e=>`<div class="dit-transmission"><span class="mono red">${escapeHtml(e.agent_id||'NETWORK')} / ${escapeHtml(e.event_type)}</span><strong>${escapeHtml(e.title)}</strong><small>${escapeHtml(e.detail||'')} · ${escapeHtml(asDate(e.created_at))}</small></div>`).join(''):'<p class="mono">NO RECORDED TRANSMISSIONS YET. BACKGROUND RESEARCH WILL APPEAR HERE.</p>'}
async function refresh(){if(refreshBusy||document.hidden)return;refreshBusy=true;try{
 const a=await request('/api/agents');roster=a.agents;votes=a.votes;healthy=await request('/api/health').catch(()=>null);
 votesBoard(roster,votes);window.dispatchEvent(new CustomEvent('dit:agents',{detail:{agents:roster,workerAlive:!!a.worker_alive}}));el('dit-auth-description').textContent=config?.auth==='dev'?'LOCAL TEST MODE — votes are not identity-verified.':sessionToken?'SIGNED IN / ACCOUNT TOKEN STORED ONLY FOR THIS BROWSER SESSION.':'A verified Supabase email account is required to vote.';
 await Promise.allSettled([displayTreasury(),displayActivity()]);
}catch(e){el('dit-live-label').textContent='BACKEND UNAVAILABLE';el('dit-vote-board').innerHTML=`<div class="dit-unavailable mono">BACKEND NOT CONNECTED — ${escapeHtml(e.message)}. Voting and live memories are not enabled yet.</div>`;}finally{refreshBusy=false}}
function status(message){el('dit-vote-status').textContent=message}
async function configInit(){try{config=await request('/api/config');if(config.auth==='none'){el('dit-sign-in').disabled=true;status('Configure Supabase Auth to enable verified votes.');}if(config.auth==='dev'){el('dit-sign-in').textContent='USE LOCAL TEST IDENTITY ↗';}}catch(e){status(e.message)} }
async function openEntity(id){if(!isAgent(id))return;const d=document.getElementById('dossier');const body=document.getElementById('dialog-content');body.innerHTML='<h2 id="dialog-title">LOADING ENTITY MEMORY…</h2>';if(!d.open)d.showModal();try{const data=await request('/api/agents/'+encodeURIComponent(id));const a=data.agent;const memories=(data.memories||[]).slice(0,8);const p=(data.proposals||[]).slice(0,6);const o=(data.observations||[]).slice(0,6);body.innerHTML=`<span class="mono red">LIVE ENTITY DOSSIER / ${escapeHtml(a.state)}</span><h2 id="dialog-title">${escapeHtml(a.id)}</h2><p>${escapeHtml(a.profile?.personality||'')}</p><dl><dt>SPECIALTY</dt><dd>${escapeHtml(a.specialty)}</dd><dt>LAST ACTIVE</dt><dd>${escapeHtml(asDate(a.last_active_at))}</dd><dt>RESEARCH WORKER</dt><dd>${data.worker_alive?'RUNNING':'OFFLINE'}</dd><dt>VOTES</dt><dd>${Number(data.votes?.votes||0).toLocaleString()} RECORDED</dd></dl><div class=\"dit-vote-actions\"><button class=\"button primary\" data-vote-entity=\"${escapeHtml(a.id)}\">VOTE FOR ${escapeHtml(a.id)}</button></div><p class=\"mono small\" id=\"dit-dossier-vote-status\" role=\"status\"></p><h3>MEMORY ARCHIVE</h3>${memories.length?memories.map(m=>`<div class="dit-memory"><span class="mono red">${escapeHtml(m.kind)}</span><p>${escapeHtml(m.summary)}</p></div>`).join(''):'<p class="mono">NO RECORDED MEMORY YET.</p>'}<h3>RESEARCH SIGNALS</h3>${o.length?o.map(x=>`<p><a class="text-link" href="${escapeHtml(/^https:\/\//.test(x.url||'')?x.url:'#agents')}" target="_blank" rel="noopener noreferrer">${escapeHtml(x.title)}</a> <span class="mono">${escapeHtml(x.category)}</span></p>`).join(''):'<p class="mono">NO VERIFIED SOURCE OBSERVATIONS.</p>'}<h3>CONCEPT PROPOSALS</h3>${p.length?p.map(x=>`<div class="dit-memory"><span class="mono red">${escapeHtml(x.status)}</span><p>${escapeHtml(x.name)} / $${escapeHtml(x.ticker)} — ${escapeHtml(x.narrative)}</p></div>`).join(''):'<p class="mono">NO GENERATED PROPOSALS.</p>'}`;
}catch(e){body.innerHTML=`<h2 id="dialog-title">ENTITY OFFLINE</h2><p>${escapeHtml(e.message)}</p>`}}
async function cast(id){if(!sessionToken){status('Sign in first to vote.');return;}status('Recording vote…');try{const data=await request('/api/vote',{method:'POST',headers:{'authorization':'Bearer '+sessionToken,'content-type':'application/json'},body:JSON.stringify({agent_id:id})});status('Your vote is recorded. You can switch favorites later.');votes=data.votes;if(roster)votesBoard(roster,votes)}catch(e){status(e.message)}}
gallery.addEventListener('click',e=>{const profile=e.target.closest('[data-open-entity]');if(profile)openEntity(profile.dataset.openEntity);const vote=e.target.closest('[data-vote-entity]');if(vote)cast(vote.dataset.voteEntity)});
async function signIn(){const email=el('dit-email').value.trim();if(!/^\S+@\S+\.\S+$/.test(email)){status('Enter a valid email address.');return;}try{
 if(config?.auth==='dev'){sessionToken='dev:'+email;sessionStorage.setItem('dit:vote-session',sessionToken);el('dit-sign-out').hidden=false;status('Local test identity active. This is NOT secure production sign-in.');await refresh();return;}
 if(config?.auth!=='supabase'||!config?.supabase){status('Supabase authentication not configured.');return;}
 const {url,anonKey}=config.supabase;const endpoint=url.replace(/\/$/,'')+'/auth/v1/otp?redirect_to='+encodeURIComponent(location.origin+location.pathname+'#agents');const r=await fetch(endpoint,{method:'POST',headers:{apikey:anonKey,'content-type':'application/json'},body:JSON.stringify({email,create_user:true})});if(!r.ok)throw Error('Authentication email request failed');status('Check your inbox for the sign-in link.');
}catch(e){status(e.message)}}
el('dit-sign-in').addEventListener('click',signIn);el('dit-sign-out').onclick=()=>{sessionToken='';sessionStorage.removeItem('dit:vote-session');el('dit-sign-out').hidden=true;status('Signed out.');refresh()};
el('dit-sign-out').hidden=!sessionToken;
// CSS 2.5D artwork motion; preserves original portraits. Only rigged GLB files can provide genuine 3D animation.
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){root.addEventListener('pointermove',e=>{const card=e.target.closest('.dit-portrait-motion');if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--motion-x',(((e.clientX-r.left)/r.width)-.5).toFixed(3));card.style.setProperty('--motion-y',(((e.clientY-r.top)/r.height)-.5).toFixed(3));});root.addEventListener('pointerout',e=>{const card=e.target.closest('.dit-portrait-motion');if(card){card.style.setProperty('--motion-x',0);card.style.setProperty('--motion-y',0);}})}
await configInit();await refresh();setInterval(refresh,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});

// Stage / realtime integration (events keep modules decoupled).
window.addEventListener('dit:open-entity',e=>openEntity(e.detail?.id));
window.addEventListener('dit:refresh',()=>refresh());
document.getElementById('dialog-content')?.addEventListener('click',async e=>{const v=e.target.closest('[data-vote-entity]');if(!v)return;await cast(v.dataset.voteEntity);const m=document.getElementById('dit-dossier-vote-status');if(m)m.textContent=el('dit-vote-status').textContent;});
